{"actions":[{"type":"success_contract","content":{"objective":"Run Windows 3.11 for Workgroups in QEMU from /app/isos/win311.img, leaving the VM running in the background at the Windows 3.11 desktop, with VNC on :1 (port 5901), nginx on port 80 for remote access, snapshot mode enabled to keep the base image immutable, and programmatic keyboard input available beyond VNC interaction.","required_artifacts":["A running QEMU process using /app/isos/win311.img in snapshot mode","A VNC listener on 0.0.0.0:5901 or equivalent for display :1","An nginx web server listening on port 80","A mechanism for programmatic keyboard input to QEMU (e.g. QMP/HMP/monitor socket or equivalent)","Receipt-backed evidence that the VM reached the Windows 3.11 desktop"],"required_behaviors":["QEMU must start successfully and remain running in the background","The VM must be configured for VNC display :1","The VNC server must be reachable on port 5901","The base disk image must not be modified because QEMU runs in snapshot mode","Keyboard input must be injectable programmatically, not only via VNC GUI interaction","nginx must be configured and listening on port 80"],"known_invalid_patterns":["Only proving files exist without starting services","Only proving QEMU launches without evidence of the Windows desktop","Only proving VNC or nginx configuration files exist without active listeners","Only proving interactive VNC access without programmatic keyboard control","Only smoke-testing commands that do not demonstrate the requested runtime behavior"],"verification_plan":["Inspect available tools and environment for QEMU, nginx, and networking support","Start QEMU with snapshot mode, VNC :1, and a monitor/QMP interface suitable for programmatic keyboard injection","Start or configure nginx on port 80 for remote access","Verify listeners on ports 5901 and 80","Use receipts to confirm the VM reaches the Windows 3.11 desktop","Confirm the VM remains running in the background and keyboard injection path is available"],"finalization_evidence_required":["Receipt showing QEMU started with snapshot mode and VNC :1","Receipt showing port 5901 is listening","Receipt showing nginx is listening on port 80","Receipt showing a programmatic keyboard control interface is configured and reachable","Receipt-backed evidence that the Windows 3.11 desktop is displayed in the VM"]}},{"type":"plan_update","content":{"status":"execution","next_steps":["Inspect environment for qemu/nginx availability and existing receipts","Launch or repair QEMU with snapshot mode, VNC :1, and monitor/QMP socket","Configure/start nginx on port 80","Verify listeners and desktop state using receipts"],"notes":["Need receipt-backed runtime evidence before finalization."]}}]}
